window.ScripturaJastrowAppend([{"sid":"Q01140","lemma":"פַּמִּילְיָיא","gloss":"Os escravos em uma casa, servos de família, freque.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּמַּלְיָא, פְּמַ&#x27;</p><p><strong>Definição:</strong> Os escravos em uma casa, servos de família, freque.</p><p><strong>Notas e referências:</strong> Agências divinas, ministros. Targ. Cant.איוב … ומגדולי פמילייא וכJó era um dos servos do Faraó e dos grandes de sua casa. 7 b; 67 bפ&#x27; של מעלהA família celestial, V.כַּשָּׁףBer. 16 b sq.שתשים שלים בפ&#x27; של מעלה ובפ&#x27; של מטהQue a paz reine na família celestial e na casa aqui embaixo. Número R.S. 4, implore.ראה המלך ופ&#x27; שלו וכ&#x27; ele viu o rei, e seus assistentes estavam ao seu lado para protegê-lo. Sifra K’dosh. Implore. Lev. 604, V.חָקָה; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"Q01141","lemma":"פַּמְיָס","gloss":"Ver פַּנְיָיס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְיָיס</p>","gloss_language":"pt-BR"},{"sid":"Q01142","lemma":"פַּמַּלְיָא","gloss":"Ver פַּמִּילְיָיא.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּמַ&#x27;</p><p><strong>Notas e referências:</strong> , v. פַּמִּילְיָיא</p>","gloss_language":"pt-BR"},{"sid":"Q01143","lemma":"פמלליא","gloss":"Ver next w..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Próximo W.</p>","gloss_language":"pt-BR"},{"sid":"Q01144","lemma":"פִּמְלַנְיָא","gloss":"Ataduras, broches.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> Ataduras, broches.</p><p><strong>Notas e referências:</strong> Ned. 55 B.פליניא(Ar.פלניא; corr. acc.). Nidd. 13 b.כמין פ&#x27; של פרשים(Vers. em Ar.פלניא) como a feminina dos cavaleiros. Gen. R. s. 84 (ref. toאשר עליו, Gen. XXXVII, 23)זו פ&#x27; שלוIsso se refere a suas calças, Yalk. ib. 142פלמניאKel. XXVII, 6פמוליניאDehr.פימלנייה). Gen. R. s. 99אלו … לובשי פמלליאEstes (os sacerdotes) usam calças, e aqueles (os gregos) usam femininalia. Número 4עטוף פעליונין(Leia:פִּמְלְיוֹנִיןEle estava embrulhado em feminina.</p>","gloss_language":"pt-BR"},{"sid":"Q01145","lemma":"פן","gloss":"Ver מְנָן.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Targ. Jon.ומפן, leiaומנן, v. מְנָן</p>","gloss_language":"pt-BR"},{"sid":"Q01146","lemma":"פֶּן","gloss":"[ Eventualmente,] não.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> פָּנָה, cmp.פּוֹן)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> [ Eventualmente,] não.</p><p><strong>Notas e referências:</strong> Zeb. 106 aכל מקום שנאמר השמר פן ואל וכOnde quer que a Escritura tenha sido guardada, para que, ou al, introduza uma lei proibitória (v.עָשָׂה); Sot. 5 a, a. fr. Sifré Deut. 70, quot. em Yalk. ib. 882השמר בלא תעשה פן בלא תעשה&quot;ser vigiado&quot; significa uma lei proibitória, e assim como &#x27;lest&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"Q01147","lemma":"פְּנָא","gloss":"Ver פְּנֵי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּנֵי</p>","gloss_language":"pt-BR"},{"sid":"Q01148","lemma":"פְּנַאי","gloss":"(פָּנָה); Vazio, vaga.; férias, lazer, tempo, oportunidade.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנַיי</p><p><strong>Definição:</strong> (פָּנָה)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Vazio, vaga.</p><p><strong>Notas e referências:</strong> Num. R.S. 14 (jogarאל תבהל מפניו, Koh. VIII, 3)לא נתבהל מפ&#x27; הביתEle (Joseph) não ficou perplexo com o vazio da casa (seu estar sozinho com a esposa de Potifar).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> férias, lazer, tempo, oportunidade.</p><p><strong>Notas e referências:</strong> Ab. Zar. V, 6לפי שאין פ&#x27; לנסךPorque os invasores não levam tempo para oferecer uma libação (para tornar o vinho proibido, v.נָסַךְ). Ib. 71 aלנסך אין פ&#x27; לבעול יש פ&#x27; para a libação não levam tempo, mas para o ultraje que fazem. Y. ib. V, 45 por topאין פ&#x27; להטיל אירסA cobra (sendo perseguida) não encontra oportunidade de derramar veneno.</p>","gloss_language":"pt-BR"},{"sid":"Q01149","lemma":"פנג","gloss":"Targ. Y. Gen. XXII, 20ופנגת, alguns Ed., leia:ופַגְנַת.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Targ. Y. Gen. XXII, 20ופנגת, alguns Ed., leia:ופַגְנַת.</p>","gloss_language":"pt-BR"},{"sid":"Q01150","lemma":"פִּנְגּוּס","gloss":"(Transp. de Pignus) penhor depositado no credor, cujo usufruto permaneceu do devedor (v. Sm. Ant. s. v. Pignus).","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פִּנְגָּס</p><p><strong>Definição:</strong> (Transp. de Pignus) penhor depositado no credor, cujo usufruto permaneceu do devedor (v. Sm. Ant. s. v. Pignus).</p><p><strong>Notas e referências:</strong> Mekh. Yithro, Bahod, s. 1 (ref. para Is. XLV, 19)לא אמרתי לזרע יעקב לאלו אני נותנה ולא תהו בקשוני לא נתתיה פ&#x27; וכ&#x27;Eu não disse, &#x27;à semente de Jacó&#x27;, a eles somente darei a Lei (e não a outras nações), nem (disse,) &#x27;Buscai-me por nada&#x27;, eu não a dei como penhor (da qual não podeis ter o usufruto), ... muito antes de vos dar as ordens, tenho-vos adiantado a recompensa por eles &amp;c; Yalk. Ex. 275; Yalk. É. 325 (omitindoלאלו אני נותנה ולא).</p>","gloss_language":"pt-BR"},{"sid":"Q01151","lemma":"פנגיות","gloss":"Ver פַּגְנוּת.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Pirké d’R. El.פגניות, v. פַּגְנוּת</p>","gloss_language":"pt-BR"},{"sid":"Q01152","lemma":"פִּנְגָּס","gloss":"Ver פִּנְגּוּס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּנְגּוּס</p>","gloss_language":"pt-BR"},{"sid":"Q01153","lemma":"פַּנְגַּר","gloss":"(uma adaptação deπανεγυρίστηςPangar, nome de um dos generais antes de Jerusalém sob Vespasiano.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Definição:</strong> (uma adaptação deπανεγυρίστηςPangar, nome de um dos generais antes de Jerusalém sob Vespasiano.</p><p><strong>Notas e referências:</strong> Lam. R. para I, 5חד אמר קילוס שמיה וחד אמר פ&#x27; שמיהUm diz que o nome daquele dux era Illus, e outro diz que o nome dele era Pangar.</p>","gloss_language":"pt-BR"},{"sid":"Q01154","lemma":"פַּנְדָּא","gloss":"Ver פַּדָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּדָּא</p>","gloss_language":"pt-BR"},{"sid":"Q01155","lemma":"*,","gloss":"Panda, 1) nome de Amora (?).","type":"Nome próprio masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: *פַּנְדָּא</p><p><strong>Definição:</strong> Panda, 1) nome de Amora (?).</p><p><strong>Notas e referências:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Notas e referências:</strong> Nome de Amora. Ber. 55 B.פבנא a. פרנא* En Yaăk. ed. pr., a. Yolăsinפרנך, v. Rabb. D. S. a. l. nota).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Notas e referências:</strong> בר שיריקא פ&#x27; nome de um demônio. Sabb. 67 a (Rashiפנדאי; Sra. M.פניא).</p>","gloss_language":"pt-BR"},{"sid":"Q01156","lemma":"פנדודה","gloss":"Ver פַּנְרּוּרָה.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְרּוּרָה</p>","gloss_language":"pt-BR"},{"sid":"Q01157","lemma":"פנדור","gloss":", leia:","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , leia:</p>","gloss_language":"pt-BR"},{"sid":"Q01158","lemma":"פַּנְדּוּרָה","gloss":"(πανδοῦρα, v. Hesych.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (πανδοῦρα, v. Hesych.</p><p><strong>Notas e referências:</strong> O tubo pandeano (syrinx), o tubo do pastor. Y. B. Bath. VII, fim, 15 dנותן לו כמין פEle deve dar-lhe uma parte de seu campo na forma de um siríngeo (um quadrângulo de um lado do qual é metade do tempo que o seu oposto). Ib. III, implore. 13 d (Expl.מַשְׁכּוֹכִיתָא) אית דמרין פ&#x27; (ed. Krot.פנדודהAlguns dizem, a libertação do cachimbo do pastor (como possessão simbólica); Y. B. Kam. X, fim, 7 c (expl.ברחא), v. שַׁרְקוּקִיתָא.</p>","gloss_language":"pt-BR"},{"sid":"Q01159","lemma":"פַּנְדֵּירָא","gloss":"Pandera, (Panêra, Panêri), sobrenome de José, pai de Jesus de Nazaré.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְדֵּרָא, , (,, פַּנְטֵירָא, פַּנְטֵרָא, פַּנְטֵירִי)</p><p><strong>Definição:</strong> Pandera, (Panêra, Panêri), sobrenome de José, pai de Jesus de Nazaré.</p><p><strong>Notas e referências:</strong> Koh. R. para X, 5חד מן אילין דבר פUm dos seguidores do filho de P.-Tosef. II, 22; 24; a. fr.; v.יֵשׁוּ.</p>","gloss_language":"pt-BR"},{"sid":"Q01160","lemma":"פנדר","gloss":"Ver קְלָאפנְדָּר.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Gen. R. s. 50, v.קְלָאפנְדָּר</p>","gloss_language":"pt-BR"},{"sid":"Q01161","lemma":"פַּנְדֵּרָא","gloss":"Ver פַּנְדֵּירָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְדֵּירָא</p>","gloss_language":"pt-BR"},{"sid":"Q01162","lemma":"פָּנָה","gloss":"Ver פני.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פני</p>","gloss_language":"pt-BR"},{"sid":"Q01163","lemma":"פָּנֶה","gloss":"Ver פָּנִים.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פָּנִים</p>","gloss_language":"pt-BR"},{"sid":"Q01164","lemma":"פִּנָּה","gloss":"Ver פִּינָּה.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּינָּה</p>","gloss_language":"pt-BR"},{"sid":"Q01165","lemma":"פָּנוּטְיָה","gloss":"Ver פָּגוּטְיָה.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פָּגוּטְיָה</p>","gloss_language":"pt-BR"},{"sid":"Q01166","lemma":"פִּנּוּי","gloss":"Ver פִּינּוּי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּינּוּי</p>","gloss_language":"pt-BR"},{"sid":"Q01167","lemma":"פָּנוּי","gloss":"(פָּנָה); Vazio, vazio, livre, supérfluo.; Single, sem casamento.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנוּיָה</p><p><strong>Definição:</strong> (פָּנָה)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Vazio, vazio, livre, supérfluo.</p><p><strong>Notas e referências:</strong> Erub. 16 bובלבד … בית סאתים פDesde que não haja uma área de dois S&#x27;ah desocupados.פ&#x27; מכליםDesocupado por instrumentos de viagem, contra. paraפ&#x27; מאדםsupérfluo em relação ao número de viajantes (a cada um dos quais uma área de dois S&#x27;ah é atribuída). Ex. R. s. 5; Tan. Vaëra 6שבטו … פ&#x27; היה מעבודת פרךA tribo de Levi estava isenta de trabalhos forçados; ed. Bub. ib. 4; Yalk. Ex. 176פְּנוּי וכ&#x27;, v. לטרגיהSabb. 23 aשלא יראה בעל הבית שעה פ&#x27; וכPara que o dono não olhe para fora por um momento livre (quando não há pobres sobre), e diga a seu pobre parente, aqui é a esquina (פֵּאָהY. Peah IV, 18 bקנויה(corr. acc.); e.פְּנוּיִים, פְּנוּיִין; פְּנוּיוֹתTan. l. c.בשביל שאתם פ&#x27; וכPorque você é ocioso, você diz Ex. R. l. c.פְּנוּיִם; a. e.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Single, sem casamento.</p><p><strong>Notas e referências:</strong> Sifra Emor, Par.הפ&#x27; הבא על הפ&#x27; שלא וכSe um homem solteiro tem conexão com uma mulher solteira sem a intenção de assim torná-la sua esposa, Yeb. 61 b; a. fr.מעין חתום, Cant. IV, 12)אלו הפנויותIsto se refere aos solteiros (homens e mulheres no Egito). Tanë. Vayesheb 8השתא הפ&#x27; שלכם אסורות לנו וכAté mesmo os solteiros do seu povo estão proibidos de nos ver, quanto mais tu, que és esposa de um homem;</p>","gloss_language":"pt-BR"},{"sid":"Q01168","lemma":"פְּנוּיַיְתָא","gloss":"Ver פְּנִיּוּתָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּנִיּוּתָא</p>","gloss_language":"pt-BR"},{"sid":"Q01169","lemma":"פִּנּוּכָא","gloss":", V. Sub.פִּינּ'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פִּנּוּקָא</p><p><strong>Notas e referências:</strong> , V. Sub.פִּינּ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"Q01170","lemma":"פַּנּוּקְטִין","gloss":"Ver פַּנִּיקְטִין.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנִּיקְטִין</p>","gloss_language":"pt-BR"},{"sid":"Q01171","lemma":"פְּנַחְיָא","gloss":"Proteção, proteção.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנַחְיָה</p><p><strong>Definição:</strong> Proteção, proteção.</p><p><strong>Notas e referências:</strong> B. Kam. 103 aמידע … ופ&#x27; הוא דקבעינא(Ms. M.פנחייהVocê sabe muito bem que eu comprei o campo para mim, e que (em comprá-lo em nome de uma terceira pessoa influente) eu tinha em vista apenas proteção (contra disputas legais). Yeb. 115bלפ&#x27; שבקיהEle deixou as cartas que deveriam marcar o conteúdo como sagrado no recipiente apenas para proteção (que poderia ser poupado por servos ladrões).</p>","gloss_language":"pt-BR"},{"sid":"Q01172","lemma":"פנחרין","gloss":"Ver פַּנְתֵּיר.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְתֵּיר</p>","gloss_language":"pt-BR"},{"sid":"Q01173","lemma":"פנטון","gloss":"Ver דומין.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Esth. R. para VI, 10, A.E., leia:פְּרִיבָטוֹן, v. דומין, a. קוֹמֵיס.</p>","gloss_language":"pt-BR"},{"sid":"Q01174","lemma":"פַּנְטוֹס","gloss":"(πάντωςDe qualquer forma.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (πάντωςDe qualquer forma.</p><p><strong>Notas e referências:</strong> Y. Snh. VI, implore. 23 b, v.נִיבְזִין.</p>","gloss_language":"pt-BR"},{"sid":"Q01175","lemma":"פַּנְטֵי","gloss":"Ver אַפַּנְטֵי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. אַפַּנְטֵי</p>","gloss_language":"pt-BR"},{"sid":"Q01176","lemma":"*,","gloss":"Pansei.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: *פַּנְטִי</p><p><strong>Definição:</strong> Pansei.</p><p><strong>Notas e referências:</strong> Koh. R. para VIII, 3לוי בן פ&#x27;; Meg. 31 bבר בוטי(Ms. M.בוטא); Trato. Sof’rim XII, 3בר פדא; Y. Meg. III, 74 b bot.פאטי(ed. Krot.פסטי; ed. Crac.פכטי); Yalk. Prov. 932בוטא.</p>","gloss_language":"pt-BR"},{"sid":"Q01177","lemma":"פֶּנְטִיגוֹן","gloss":"(πεντάγωνος) pentagonal.; (πεντάγονος) pela quinta vez.; Cinco vezes.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פִּינְ&#x27;, פּוּנְ&#x27;</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> (πεντάγωνος) pentagonal.</p><p><strong>Notas e referências:</strong> Naz. 8 b; B. Bath. 164 bפ&#x27; (בית) um edifício pentagonal, Tosef. Neg. VI, 3פנטיגיןEd. Zuck.פנטניז, corr. acc.).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> (πεντάγονος) pela quinta vez.</p><p><strong>Notas e referências:</strong> Naz. l. c.; B. Bath. l. c., v.דִּיגוֹן.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Cinco vezes.</p><p><strong>Notas e referências:</strong> Midr. Até mais. para Ps. LXXVIII, 49פ&#x27; היה(nãoהיא; ed. Bub.טטראגון הואCada praga egípcia era cinco vezes maior.</p>","gloss_language":"pt-BR"},{"sid":"Q01178","lemma":"פַּנְטֵירָא","gloss":"Ver פַּנְדֵּירָא.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְטֵירִי</p><p><strong>Notas e referências:</strong> , v. פַּנְדֵּירָא</p>","gloss_language":"pt-BR"},{"sid":"Q01179","lemma":"פַּנְטֵירִי","gloss":"Ver פַּנְתֵּירִי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְתֵּירִי</p>","gloss_language":"pt-BR"},{"sid":"Q01180","lemma":"פנטיתא","gloss":"Ver בָּטְנִיתָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. בָּטְנִיתָא</p>","gloss_language":"pt-BR"},{"sid":"Q01181","lemma":"פנטניז","gloss":"Ver פֶּנְטִיגוֹן.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פֶּנְטִיגוֹן</p>","gloss_language":"pt-BR"},{"sid":"Q01182","lemma":"פַּנְטַסְכִינָאֵי","gloss":"Nom.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְטַסְכְנָ&#x27;</p><p><strong>Definição:</strong> Nom.</p><p><strong>Notas e referências:</strong> Sr. Pl.πεντάσχοινος) habitantes de Pentaschoinos, um distrito egípcio [prob. destinado a Dodekaschoinos, por confusão com o próximo w.]. Targ. I Chr. I, 11 (ed. Rahmerפנטסכיינ&#x27;); Targ. Y. I Gen. X, 13 (h. texto)נפתחים); Targ. Y. II ib. 14 (ed. Amst.פְּנַטְסַכְנָ&#x27;; h. textoכסלחים).</p>","gloss_language":"pt-BR"},{"sid":"Q01183","lemma":"פנטפולוטי","gloss":"Ver next w..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , V. Próximo W.</p>","gloss_language":"pt-BR"},{"sid":"Q01184","lemma":"פַּנְטַפּוֹלִיטָאֵי","gloss":"Nom.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> Nom.</p><p><strong>Notas e referências:</strong> Sr. Pl.πενταπολῖται) habitantes de Pentápolis, um distrito egípcio (também chamado de Cyrenaica). Targ. I Chr. I, 12פתרסים; Targ. Y. I Gen. X, 14 (ed. Vien.פַּנְטַפּוּלוֹטֵי; H. textoכסלחים[Targ. Y. II ib. 13 (ed. Vien.פַּנְטַפּוֹלַטָ&#x27;; h. textoענמיםouלהבים), prob. deslocado; v. preced. art.]</p>","gloss_language":"pt-BR"},{"sid":"Q01185","lemma":"פֶּנְטַקָקָה","gloss":"Penzaah, sobrenome de alguém que foi dito ter cometido cinco pecados (πέντα κακάTodos os dias.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Definição:</strong> Penzaah, sobrenome de alguém que foi dito ter cometido cinco pecados (πέντα κακάTodos os dias.</p><p><strong>Notas e referências:</strong> Y. Taan. I, 64 B bot.</p>","gloss_language":"pt-BR"},{"sid":"Q01186","lemma":"פַּנְטֵרָא","gloss":"Ver פַּנְדֵּירָא.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְטֵרִי</p><p><strong>Notas e referências:</strong> , v. פַּנְדֵּירָא</p>","gloss_language":"pt-BR"},{"sid":"Q01187","lemma":"פַּנְטֵרִי","gloss":"Ver פַּנְתֵּירִי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְתֵּירִי</p>","gloss_language":"pt-BR"},{"sid":"Q01188","lemma":"פני","gloss":"(b. h.); Para virar (o rosto de alguém).; Vire-se, vá embora.; (ato. verbo) para virar, pervertido.; para se virar, sair, (eufem.) para aliviar a si mesmo.; para sair (v. infra); para libertar, liberar.; para esvaziar, remover, transferir.; para libertar, absolver.; Virar.; ser removido, morrer.; ser livre, no lazer.; para aliviar a si mesmo.; para ser liberado.; Para sair.; para ser desocupado, liberado, removido.; para ser liberado.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פָּנָה</p><p><strong>Definição:</strong> (b. h.)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para virar (o rosto de alguém).</p><p><strong>Notas e referências:</strong> Yoma 17 B, A.E.שאתה פוֹנֶה, v. פִּינָּהY. Ab. Zar. III, 42 b sq (ref. para Lev. XIX, 4)אל תִּפְנֶה לעובדןNão se vire para eles para adorá-los;אל תפנה לראותן ממשNão vire o rosto para olhar para eles, Sifra K&#x27;dosh. Implore.אל תפנה לראותם וַדַּייIb.תחלתם אלילים הם אם פּוֹנֶה את אחריהן וכNo início, não são nada, mas se os perseguires, tu os farás deuses. Lev. 604.אל תִּפְנוּ אֶל מדעתכםA. v. fr.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Vire-se, vá embora.</p><p><strong>Notas e referências:</strong> Lam. R. para I, 1כיון ששתה ופ&#x27; לילך (מעשה) רבתיquando ele tinha bebido e se virou para ir embora. Gen. R. s. 68יצא משם פ&#x27; זיוה פ&#x27; הדרהQuando ele (os justos) vai embora de um lugar, seu esplendor se foi, sua glória se foi, Ruth R. para I, 7.ונתתי את פני, Lev. XX, 6; cmp.פְּנַאי) פּוֹנֶה אני מכל וכ&#x27;, v. עֵסֶקMidr. Prov. a XVI, 11לִפְנוֹת היוםQuando o dia estava passando (para a noite);</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> (ato. verbo) para virar, pervertido.</p><p><strong>Notas e referências:</strong> Cant. R. para VII, 9אח̇ש̇ד̇רפ̇נ̇יא, Dan.אלו ארכונות שהן נש̇ח̇ד̇ין ופ̇וני̇ן דין וכ&#x27; (NãoנחשדיןEsses são os oficiais que são subornados e fazem justiça em qualquer direção, ib.שמה̇ד̇ר̇ין פ̇נ̇ים ופ̇ונ̇ין דיןque respeitam as pessoas e pervertem a justiça.</p><p><strong>Número da acepção:</strong> —4)</p><p><strong>Definição:</strong> para se virar, sair, (eufem.) para aliviar a si mesmo.</p><p><strong>Notas e referências:</strong> Y. Sot. I, 16 dאם יִפְנֶה אחד מהן לצורכוSe um deles sair por uma necessidade humana. Toh. X, 2ופוֹנִים(Ber. 62 aונִפְנִין, Nif.).</p><p><strong>Número da acepção:</strong> —5)</p><p><strong>Definição:</strong> para sair (v. infra); para libertar, liberar.</p><p><strong>Notas e referências:</strong> Pesik. R.S. 42הספינה … ולא תטריח עליה לִפְנוֹתָהּ(nãoהטריחO navio de seu amigo foi apreendido (para o serviço público), e você não vai se esforçar para libertá-lo?ועכשיו של אחרים הוא פוֹנֶה ושלו אינה נפניתe agora ele liberta os navios de outros homens, e não será que o seu será libertado? Parte, passo.פָּנוּי; f. פְּנוּיָהVazio, vazio, livre. Ber. 43 aאין בית הבליעה פSeu esôfago não é livre (o que torna a fala perigosa). Y. Kil. III, implore. 28 cאי אפשר … נקב אחד פ&#x27; וכNão é possível que não haja uma cavidade livre para plantar Y. Sabb. IX, 11 d bot.אפשר … פניי(corr. acc.). Num. R.S. 14והיה הבית פE a casa estava vazia (nenhuma em casa);פָּנוּי.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para esvaziar, remover, transferir.</p><p><strong>Notas e referências:</strong> Sabb. III, 5המיחם שפִּינָּהוּ וכNa chaleira que se esvaziou (ou: qual foi removido do forno)המיחם שפ&#x27; ממנו מים וכNa chaleira da qual se removeu a água quente. Ib. XVIII, 1מְפַנִּין אפי&#x27; וכ&#x27; você pode limpar (no sábado) até quatro ou cinco pilhas ... para dar espaço para os hóspedes. Y. Gitt. VIII, 49 d topאם … איש מְפַנֶּהSe o tribunal pertence à esposa, o marido (após o divórcio) deve desocupá-lo,ושל איש אשה מְפַנָּהE se pertence ao marido, a esposa deve desocupá-lo;מי מפנה מפני מיQual deles deve desocupar para o outro? Taan. 21 aבקשו תלמידיו לפַנּוֹת את וכ&#x27; seus discípulos queriam mover sua cama primeiro e depois seus móveis;פַּנּוּ את הכלים וכ&#x27; mover os móveis primeiro. Ab. III, 4מפנה לבו לבטלהesvazia seu coração (de pensamentos sérios para abrir espaço) para assuntos frívolos. Sabb. 149 a (ref. para Lev. XIX, 4, v. supra)אל תְּפַנוּ אֵל מדעתכםNão removam Deus de suas mentes. B. Kam. 81 bמְפַנֵּיהוּ לשדה וכ&#x27; ele deve remover o cadáver para &amp; C. Y. Maasr. II, 49 dרוצה אדם לפנות עסקיו וכ&#x27; (ed. Krot.רוצה הוא אדם לפנע; ed. Zyt.לפלהUm homem está ansioso para se livrar de seus bens.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para libertar, absolver.</p><p><strong>Notas e referências:</strong> Tanë. Vayikra 6פ&#x27; לקרתני ולבן פלטרין וכEle absolveu o plebeu, mas condenou o cortesão. Ib.לקרתני פִּנִּיתִי וכEu absolvi o plebeu, porque ele não conhece os costumes reais.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Virar.</p><p><strong>Notas e referências:</strong> Midr. Até mais. a Sal. XVIII, 5נִפְנֵיתִי לכאן וכVirei em todas as direções, e não há redentor além de ti, Yalk. Sam. 157.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> ser removido, morrer.</p><p><strong>Notas e referências:</strong> Gen. R. s. 98שהיה נ&#x27; מן העולםque ia morrer. Tosef. Par. III (II), 8נ&#x27; בניMeu filho está morto.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> ser livre, no lazer.</p><p><strong>Notas e referências:</strong> na mesma fonteלכשאֶפָּנֶה לךquando terei lazer para ti, ou seja. Eu me vingarei de ti, quando a oportunidade oferecer;אמר לו כשתִּפָּנֶהEle disse a ele, quando você deve estar em lazer (ou quando você deve estar morto, v. supra); ib. (Vers. de R.S. para Par III, 8)לא נ&#x27; בני שהעריב שמשוMeu filho não encontrou descanso (para se vingar), pois seu sol se pôs (ele está morto). Ab. II, 4אל תאמר לכשאפנה אשנה שמא לא תפנהNão diga, quando eu estiver em lazer, eu estudarei, talvez você nunca encontre lazer, a. fr.</p><p><strong>Número da acepção:</strong> —4)</p><p><strong>Definição:</strong> para aliviar a si mesmo.</p><p><strong>Notas e referências:</strong> Sabb. 82 aהנצרך לִפָּנוֹת ואינו נפנהAlf.להִפָּנוֹתEle que sente a necessidade de se acalmar, e não está aliviado.הנצרך ליפנות ואינו יכול ליפנותBer. 62 aונִפְנִין, v. supra; a. fr.</p><p><strong>Número da acepção:</strong> —5)</p><p><strong>Definição:</strong> para ser liberado.</p><p><strong>Notas e referências:</strong> Pesik. R.L.C., v. supra.</p><p><strong>Definição:</strong> Para sair.</p><p><strong>Notas e referências:</strong> - Parte, passo.מוּפְנֶהA) livre, desactivado, solteiro. Yeb. III, 5שלשה אחין … ואחד מTrês irmãos dois dos quais foram casados com duas irmãs, e um é livre (não casado ou casado com um que é um estranho para as esposas de seus irmãos); Y. ib. III, 4 d top; a. e.- b) (exegese dialética) livre para interpretação, desnecessária para o sentido ou contexto simples. Nidd. 22b.וייצר מ&#x27; משני צדדין מ&#x27; … ומ&#x27; גבי בהמהVayitser é livre para interpretação de ambos os lados, é livre em relação ao homem (Gen. II, 7, porque a criação do homem é mencionada emויברא, ib. I, 27), e livre em relação aos animais (ib. II, 19, sua criação sendo declarada emויעש, ib. I, 25). Ib.כל גזירה שוה שאינה מוּפְנָה כל עיקר וכPalavras análogas que não são inteiramente livres (em ambos os textos) não podem ser feitas a base para interpretação como g&#x27;zerah shavah (v.גְּזֵרָה). Ib.מ&#x27; מצד אחדLivre em um dos textos:</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para ser desocupado, liberado, removido.</p><p><strong>Notas e referências:</strong> Y. Naz. IX, 57 d bot.כל הקברות מִתְפַּנִּין וכTodas as sepulturas podem ser desocupadas (transferidas), exceto o tratamento. Sâma. Ch. XIV.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para ser liberado.</p><p><strong>Notas e referências:</strong> Pesik. R.L.C.כדי הוא (ש)תִּיתְפִּנֶּהEle merece que sua nave seja libertada.כדי הוא שיִתְפַּנֶּהEle merece ser libertado).</p>","gloss_language":"pt-BR"},{"sid":"Q01189","lemma":"פְּנֵי","gloss":",; Para ir ou vir, para ir.; Para remover, vazio, V. infra.; para aliviar a si mesmo.; Para limpar, esvaziar, remover.; para libertar, absolver.; para aliviar a si mesmo.; Virar, direto, levar de lado.; Para desocupar, livre, para levar tempo.; para aliviar a si mesmo.; Virar, ir embora.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנָא</p><p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para ir ou vir, para ir.</p><p><strong>Notas e referências:</strong> Targ. Y. Gen. XXIV, 49 (O. Ithpe.). Targ. XXIX, 17 anos. Targ. O. Gen. XXIV, 63למִפְנֵי רמשא(Ed. Amst.למִפַּנֵּיIthpa.כמִפְנֵי רמשאNa volta da noite. Gen. R. s. 63שלח … מִפְנֵי רמשא דערובתאenviou cartas para Tiberíades (para chegar aos anciãos) na noite de sexta-feira; (Y. Ter. VIII, 46 b bot.בערובתא עם מטמעי שמשא; a. fr.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para remover, vazio, V. infra.</p><p><strong>Notas e referências:</strong> , v. infra.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para aliviar a si mesmo.</p><p><strong>Notas e referências:</strong> Ber. 62 aדבעינא למִפְנֵי(Ms. F.לאַפְנוּיֵיAf.).</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para limpar, esvaziar, remover.</p><p><strong>Notas e referências:</strong> Targ. Y. Gen. XXIV, 20 Ar.ורוקינת; H. textoותערTarg. Ps. LXXX, 10 (ed.פָּנִיTarg. O. Gen. XXIV, 31 (Y. Pe.). Targ. Is. XL, 3; A.F. — Parte. Passo.מְפַנָּאLimpo, nivelado. Targ. Gen. XIV, 17 (O. ed. Vien.מַפְנָא-Ber. l. c.פַּנּוּ לי דוכתאSrta.פַּנִּי, v. Rabb. D. S. A. l. nota) limpar um lugar para mim. Taan. 20 b.בעי לפַנּוּיֵיהQueria removê-lo (o vinho);משכיה בשמעתא עד דפַנְּיֵיהEle o manteve envolvido em discussões sobre uma tradição até que ele a removeu. Lam. R. para V, 1 (Expl.ערו, Ps. CXXXVII, 7)פַּנּוּן פנוןClaro, claro (o lugar, com árbitro. paraותער, Gen. XXIV, 20, V. supra), contra. paraפגר; Pesik. Zakhor, p. 26פאטן(lerפָּאנוּן); ib. niya, p. 135 a; pesik. r. s. 32; a. fr.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para libertar, absolver.</p><p><strong>Notas e referências:</strong> Y. Ber. IX, 13 o quadrado.פַּנִּינָן יתיה, v. דֵּיוY. Taan. I, 64 B bot.מה מיעבד ומְפַנִּינֵיהO que fazer para libertá-lo da prisão?הא לך פַּנְּיִי בעליךAqui está o dinheiro para ti, liberta teu marido.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para aliviar a si mesmo.</p><p><strong>Notas e referências:</strong> Y. Sabb. VI, bot 8 c.עאל לפַנּוּיֵיה(nãoלפונייהEle foi se acalmar (v. infra).</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Virar, direto, levar de lado.</p><p><strong>Notas e referências:</strong> Targ. II Sam. III, 27. Josh. XXIV, 23 anos.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para desocupar, livre, para levar tempo.</p><p><strong>Notas e referências:</strong> Targ. Não. II, 9לית דמַפְנֵי וכNinguém leva tempo para ficar parado Esp. para tornar um texto livre para interpretação, para usar comoמוּפְנֶה(V. preced.) Nidd. 22 b.ויברא לגופיה וייצר לאַפְנוּיֵיvayibra (Gen. I, 27) é necessária para o seu próprio bem (para afirmar o fato), vayitser (ib. II, 7) deve ser usado para interpretação. Sabb. 64 aבגד ועור … שמע מינה לאפנוייQue necessidade havia de mencionar novamente o vestuário e a pele em conexão com coisas rastejantes? Aprenda com isso, que é para ser usado para fins exegéticos. Ib.; Snh. 40bלאי אפנויי וכ&#x27;, v. לַאי- Parte, passo.מַפְנֵיSabb. l. c.מ&#x27; דאי לא מ&#x27; וכM. (ed.ומופנה דאי לאו מופנהÉ livre para exegese, porque se não fosse livre (mas necessário para o seu próprio bem) &amp;c. Ib.דמת נמי אפנויי מEd. Sonc. a. Ven.מופנהA. fr.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para aliviar a si mesmo.</p><p><strong>Notas e referências:</strong> Ib. 140bלא תִיפְנוּן היכא דמַפְני וכNão vá para o mesmo lugar que seus homens usam &amp; c. Ber. 62 a, v. supra.</p><p><strong>Definição:</strong> Virar, ir embora.</p><p><strong>Notas e referências:</strong> Targ. Ex. III, 3 sq Targ Jud. XIX, 8, a. fr. - Kid. 65 aעד דמִיפְּני פיסחא(prob. para ser lido:עד מ&#x27;) até a Páscoa passar.</p>","gloss_language":"pt-BR"},{"sid":"Q01190","lemma":"פּנַי","gloss":"Ver פְּנִים.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: לִפְנַי</p><p><strong>Notas e referências:</strong> , v. פְּנִים</p>","gloss_language":"pt-BR"},{"sid":"Q01191","lemma":"פְּנֵי","gloss":"c. = h. פָּנוּי; Livre (de serviço).; Vazio.; Virando, inquieto.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פָּנֵי, פַּנְיָא, (פַּנְיָה, ) I</p><p><strong>Definição:</strong> c. = h. פָּנוּי</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Livre (de serviço).</p><p><strong>Notas e referências:</strong> Targ. D. XXIV, 5 (O. Ed. Berl.פְּ&#x27;; h. textoנקי).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Vazio.</p><p><strong>Notas e referências:</strong> Gen. R. s. 65, v.סוּלְגִּיתָא; Koh. R. a V, 10; Yalk. Gen. 115, a. e.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Virando, inquieto.</p><p><strong>Notas e referências:</strong> Midr. Até mais. a Sal. XVIII, 5 (Expl.אפפוניib.)פניא אנא מן עקיא(ed. Bub.פנייא מן עקתא אנאEstou inquieto por causa de problemas.</p>","gloss_language":"pt-BR"},{"sid":"Q01192","lemma":"פַּנְיָא","gloss":"(פְּנֵי; sub.דרמשאouדשמשא) tarde, pôr do sol, noite; primeira parte da noite.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְיָיא</p><p><strong>Definição:</strong> (פְּנֵי; sub.דרמשאouדשמשא) tarde, pôr do sol, noite; primeira parte da noite.</p><p><strong>Notas e referências:</strong> Targ. General XLIX, 27 anos. Y. Lev. VII, 16.אפ&#x27; דמעלי שבתא הוהFoi numa sexta-feira à noite. Yoma 14 bולפ&#x27; מדו ליהE, à noite, polvilham sobre ele; ib. 19 aלבהדי פ&#x27;, להדי פ&#x27;; a. e.</p>","gloss_language":"pt-BR"},{"sid":"Q01193","lemma":"פַּנְיָא","gloss":"נְהַר פַּ'N’har (Canal de) Pania em Babilônia.","type":"pr. n.","detailsHtml":"<p><strong>Definição:</strong> נְהַר פַּ&#x27;N’har (Canal de) Pania em Babilônia.</p><p><strong>Notas e referências:</strong> Gitt. Bot 65 b.</p>","gloss_language":"pt-BR"},{"sid":"Q01194","lemma":"פַּנְיָאס","gloss":"Ver פַּנְיָיס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פַּנְיָיס</p>","gloss_language":"pt-BR"},{"sid":"Q01195","lemma":"פְּנִיּוּתָא","gloss":"(פְּנֵי; cmp.פְּנַאי) se afastando de tudo, negócios especiais.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנוּיַיְתָא</p><p><strong>Definição:</strong> (פְּנֵי; cmp.פְּנַאי) se afastando de tudo, negócios especiais.</p><p><strong>Notas e referências:</strong> Targ. Y. Lev. XX, 6 (cmp.פָּנָה); ib. 3 (פְּנוּיָי&#x27;); 5; a. e.</p>","gloss_language":"pt-BR"},{"sid":"Q01196","lemma":"פְּנַיי","gloss":"Ver פְּנַאי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּנַאיSabb. IX, 11 d bot., leia:פָּנוּי, v. פָּנָה]–לִפְנַיי, v. פְּנִים.</p>","gloss_language":"pt-BR"},{"sid":"Q01197","lemma":"פַּנְיָיס","gloss":"Paneas (Cæsaræa Philippi, moderno Bânias), uma cidade no norte da Palestina.","type":"pr. n. pl.","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְיָאס, פַּמְיָיס</p><p><strong>Definição:</strong> Paneas (Cæsaræa Philippi, moderno Bânias), uma cidade no norte da Palestina.</p><p><strong>Notas e referências:</strong> Targ. Y. I Num. XXXIV, 11מערת פניאס(nãoסניאס); (Y. IIאפמים, אפמיס; ib. 10אפמיאה, אפמיאם, v. אַפַּמְיָא). Targ. Cant. V, 4פָּמִיאַס(algum Ed.פָּמְיַסTarg. I Chr. XXI, 2דן- Sim, Shebi. IX, 38 d bot.דיקליטינוס אעיק לבני פנDiocleciano oprimiu os habitantes de P. Y. Dem. II, 22 d topo. Gen. R. s. 63נחת … בהדא פנ&#x27; (Var.פמ&#x27;) ele (Diocleciano) desceu e fez sua estadia em P. Meg. 6 a; Bekh. 55 aלשם זו פמ&#x27;Leshem é P.; Tan. Ki Thissa 14ליש זו פLayish é P.; Pirké d’R. EI. ch. XXVIIדן הוא פDan é P.; Midr. Sam.דנה, II Sam. XXIV, 6)דנה פ&#x27;. Gen. R. s. 33מעיין … מערת פA primavera... da caverna de P.; Bekh. l. c.ירדן יוצא ממערת פA Jordânia emite da caverna de P.; B. Bath. 74 B.-Yalk. Deu. 820 (Moisés reza)אכנס לה במחילה … מתחת לפַמְיָסDeixe-me entrar na Palestina pela caverna de César, que está abaixo de P.; Mekh. B’shall., Imamal., s. 2לפניי ולפניםNaso 10, Num.יברכד … וישמרך שלא תהא עשוי במדינת פ&#x27; וכO Senhor te abençoe com riqueza, e te proteja, para que não sejas forçado (a tomar posse) na cidade (ou distrito) de P., e nenhuma zimia (v.זִימְיָא) ser decretado sobre a cidade, e dizem a você, dar ouro (uma referência a extorsões romanas, v. supra).</p>","gloss_language":"pt-BR"},{"sid":"Q01198","lemma":"פָּנִים","gloss":"C.P.L. (B.H.;פָּנָה) frente, rosto; semblante, pessoa.; está fechado de todos os lados e aberto na frente, então você não está autorizado a perguntar o que está acima e o que está abaixo, o que foi antes eo que será depois; [oth. opin.מה לפ' ומה לאחורo que está no extremo leste além da esfera, e o que no oeste; v., no entanto, Rashi Hag. l. c. (11 b), a. ib.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> C.P.L. (B.H.;פָּנָה) frente, rosto; semblante, pessoa.</p><p><strong>Notas e referências:</strong> Pesik.פ&#x27; זעופות) פ&#x27; זועפות, v. זָעַף. Mekh. B’shall., Vayassa, s. 2; Yalk. Ex. 258, V.חָשׁוּךְGen. R. s. 91 (ref. para Gen. XLI, 56)אין פְּנֵי הארץ אלא עשירים&quot;A face da terra&quot; significa os ricos;בזמן שאדם עשיר יש לו פ&#x27; שמחים וכQuando um homem é rico, ele tem um semblante que é feliz em ver seu amigo, mas quando ele é pobreאין לו פ&#x27; לראות וכ&#x27; ele não tem o rosto para ver (seu amigo), porque ele está envergonhado &amp;c. Keth. 7 bוהוא שבאו פ&#x27; חדשותdesde que apareça um novo rosto, ou seja, uma pessoa que não tenha assistido às festividades do casamento antes disso. Ib. 8 aאי איכא פ&#x27; חדשותSe houver um novo convidado.פ&#x27; חדשות באו לכאןAs coisas assumiram um novo rosto, ou seja, o objeto após sua transmutação não é mais o mesmo que o roubado.נשא פ&#x27;; גלה פ&#x27; &amp;c., v. נָשָׂא, גָּלָהCant. R. a VII, 9מהדרין פ&#x27;, v. פָּנָה.—לחם הפ&#x27;, v. לֶחֶםEuphem.פ&#x27; של מטה, ouפPudenda. Sabb. 41 a. Ber. 24 a.יכולה לכסות פָּנֶיהָ וכEla pode cobrir sua nudez 14 b; a. fr. - aspecto, maneira, forma de interpretação. Cant. R. para II, 4התורה שנדרשת מ&quot;ט פ&#x27; טהור ומ&quot;ט פ&#x27; טמאA Torá sobre as leis das quais os argumentos são mantidos, quarenta e nove em favor de &#x27;limpo&#x27; (permitido), e quarenta e nove em favor de &#x27;impuro&#x27; (proibido); Num. R. s. 2תורה שהיא נדרשת מ&quot;ט פA Torá, que é interpretada de 49 maneiras.לְפָ&#x27;a) por causa da aparência, formalmente. Meg. 12 aהם לא עשו אלא לפ&#x27; … אלא לפEles (em reverência ao ídolo) agiam apenas para mostrar (rendindo-se à força), então o Senhor tratou com eles apenas formalmente (não totalmente sério, ref. a Lam III, 33). b) na frente; (de tempo) antes disso, no passado. II, 1מה לפ&#x27; ומה לאחורO que foi antes (criação) e o que será no futuro (quando o mundo não existir mais; Gen. R. s. 1מה בי&quot;ת זה סתום … ופתוח מִלְּפָנָיו וכ&#x27; como a cartaב(deבראשית, Gen. I,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> está fechado de todos os lados e aberto na frente, então você não está autorizado a perguntar o que está acima e o que está abaixo, o que foi antes eo que será depois; [oth. opin.מה לפ&#x27; ומה לאחורo que está no extremo leste além da esfera, e o que no oeste; v., no entanto, Rashi Hag. l. c. (11 b), a. ib.</p><p><strong>Notas e referências:</strong> 16 a] — Ber. 5 bלפני מטתיNa frente da minha cama, expl.סמוך למיטתיimediatamente após a ascensão. Ib. 7 a, a. fr.יהי רצון מִלְּפָנֶיךָ(abbrev.יהר&quot;מQue seja a tua vontade. Ib.יהי רצון מִלְּפָנַיQue seja minha vontade. Ib.שלשה דברים בקש משה מִלִּפְנֵי וכPor três coisas que Moisés rezou diante do Senhor. Ib. I, 4שתים לְפָנֶיהָDuas benedições anteriores a ele (a leitura dos Sh&#x27;m&#x27;a); a. v. fr. — Sifra Vayikra, obah, Par. 13, ch. XXIIIאמש ושֶׁלְּפָנָיו ושֶׁלִּפְנֵי פנָיוOntem e anteontem, e anteontem.לִפְנֵי עִוֵּר(tambémלפניSó, V.עִוֵּרI) a lei proibindo um ato que pode levar uma pessoa ao pecado (Lev. XIX, 14). Ab. Zar. 14 aוליחוש … אל&#x27; מפקדינן אל&#x27; דל&#x27; לא וכ&#x27; (Ms. M.אל&#x27; עורMas não devemos prender, para que ele possa vender (o incenso) para os outros, quem irá queimá-lo para ídolos? Disse A., somos ordenados a nos proteger contra um ato que leva diretamente ao pecado, mas não contra aquele que pode indiretamente causar pecado; ib. 21 a.-מִפְּנֵיPor causa de...מפני ש־Porque... Sabb. II, 5מ&#x27; שהוא מתיירא מ&#x27; גוים וכPorque ele tem medo de invasores, de ladrões, ou de um vento mau. Ber.וסכנתי בעצמי מ&#x27; וכ&#x27;, v. סָכַןII. Ib. 3 aמ&#x27; מה נכנסת וכPor que entraste nestas ruínas? Ib.מ&#x27; שלשה דבריםpor três razões;מ&#x27; חשדPorque você dá motivo para suspeitar;מ&#x27; המפולתporque detritos podem cair sobre você;מ&#x27; המזיקיןPor causa de demônios, A.V.F.בִּפְנֵיNa presença de... Ib.b.ב&#x27; המתna presença de uma pessoa morta. Ib. 31b.המורה הלכה ב&#x27; רבוAquele que dá uma decisão na presença de seu professor.הנודר עד פְּנֵי פסח וכ&#x27;; Ned. VIII, 2הנודר עד לִפְנֵי הפסח וכ&quot;Se alguém diz em seu voto, &quot;até p&#x27;né (lifné) Páscoa&quot;, R. M. diz, ele é obrigado até o início da Páscoa; R. J. diz, até que seja passado; Kidd. 65 a, v.פְּנֵי I.</p>","gloss_language":"pt-BR"},{"sid":"Q01199","lemma":"פְּנִים","gloss":"V. I Reis VI, 29 anos.ἐνώπια) [o que está na sua frente quando você entra,] dentro, interior;לִפְנַי (וְ)לִפְO mais íntimo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.,</p><p><strong>Definição:</strong> V. I Reis VI, 29 anos.ἐνώπια) [o que está na sua frente quando você entra,] dentro, interior;לִפְנַי (וְ)לִפְO mais íntimo.</p><p><strong>Notas e referências:</strong> Tosef. Yom. II, 5היו מסיקין מבחוץ והיה נאפה ונרדה מבפ&#x27; eles aqueceram o forno em direção ao exterior (colocou o combustível na frente), e ele (o show-pão) foi cozido e retirado do interior; Yoma 38 a, v.נָסַקB. Mets. 16 aזו אינה צריכה לפ&#x27; esta (pergunta) não precisa ser trazida para dentro (a faculdade);צריכה לפ&#x27; ולפני לפEle deve ser trazido para dentro e até para o interior. Y. Kil. IX, bot 32 b.יכנס … לפQue o mais velho vá para o interior (para os bancos dianteiros);לפ&#x27; ממניNa minha frente?ר&#x27; … לפ&#x27; ור&#x27; ישמעאל … לפני לפ&quot;R.&quot; &quot;...para o interior, R.I.&quot; &quot;...para o interior (o primeiro); Y.Keth. XII, 35 por bot.&quot;לפני ולפY. Yeb. VI, 7 Cאחותו לעולם היא (מִ)בִּפְ&#x27; וכA irmã de um padre está sempre lá dentro (membro da família sacerdotal), até que ela saia (pelo casamento). Sabb. I, 1.לפ&#x27; משורת הדין, v. דִּיןII.-Esp. os recintos do Templo, o Templo e a corte dos sacerdotes;לפני ולפO mais íntimo, Santo dos Santos. Ab. Zar. 50 a.בעינא כעין פ&quot;(para um presente a um ídolo ser permanentemente proibido de uso, mesmo após o cancelamento,) é necessário que seja como as oferendas no interior do Templo (sacrifícios, incenso &amp; c., com a exclusão de presentes votivos como velas, jóias &amp; c.). Homens. 9 aלא בעיא בפ&#x27; não deve necessariamente ser feito dentro das delegacias do Templo, opp.חוץ לחומת העזרהIb.נהי … פ&#x27; מיהת בעיאEmbora possa ser feito por um não-sacerdote, pelo menos deve ser feito dentro da &amp;c. Y. Yoma V, 42 b bot.כלפי לפEm direção ao interior.מהו מבפ&#x27; (מהו) מבחוץPertence dentro (ao Santo dos Santos) ou fora (ao Santo)?, v.טְרַקְסִין.</p>","gloss_language":"pt-BR"},{"sid":"Q01200","lemma":"פְּנִימוֹן","gloss":"P’nimon.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Definição:</strong> P’nimon.</p><p><strong>Notas e referências:</strong> Y. Ter. III, fim, 42 b.אבא פAbba P.-Num. R.s. 9 (Tosef. Sot. I, 1 Var. ed. Zuck.פלימו, Y. ib. I, 16 c bot.מיניימין).</p>","gloss_language":"pt-BR"},{"sid":"Q01201","lemma":"פְּנִימִי","gloss":"interior, interior, interior, central.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנִימִית</p><p><strong>Informações do original:</strong> Denom. deפְּנִים)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> interior, interior, interior, central.</p><p><strong>Notas e referências:</strong> Erub. 65 b.ישראל ונכרי בפ&#x27; וכSe um israelita e um gentio viverem na corte interna, e um israelita na corte externa. Ib.פ&#x27; במקומו מהוOusar o residente da corte interna mover as coisas dentro de suas delegacias? Tanë. Naso 5פתח את הפ&#x27; וכEle abriu a porta central e foi para o quarto exterior. Zeb. 51 a, a. fr.מזבה הפ&quot;O altar interior (no Santo);פלמוני, Dan. VIII, 13)תרגם עקילס לפ&#x27; … לפנים ממלאכי וכ&quot;Aquila traduziu para aquele que estava dentro&quot;, o que significa Adão cujo assento particionado estava na frente dos anjos ministradores (v.פְּנִים); Yalk. Dan. 1066.פְּנִימִיִּים; f. פְּנִימִיּוֹתZeb. 52b.דמים הפ&#x27; sangue para ser polvilhado no Santo;שיריים הפOs restos de sangue espalhados no Santo. Tam. I, 4; Y. Yoma II, 39 c, v.אָכַל; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"Q01202","lemma":"פניקא","gloss":", Lev. R. s. 26 alguns ed., v.פָּגָנִיקָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Lev. R. s. 26 alguns ed., v.פָּגָנִיקָא.</p>","gloss_language":"pt-BR"},{"sid":"Q01203","lemma":"פַּנִּיקְטִין","gloss":"(παννύκτοι = παννύχιοι, S.) relógios a noite toda (pervigilia), em gen. Campos.","type":"Substantivo masculino plural","detailsHtml":"<p><strong>Definição:</strong> (παννύκτοι = παννύχιοι, S.) relógios a noite toda (pervigilia), em gen. Campos.</p><p><strong>Notas e referências:</strong> Targ. Ps. LXVIII, 30מפַּנִּיקְטֵיהוֹןAr. A. Sra. (ed.מִפַּנְקְטֵי&#x27;, Ed. Wil.מְפַ- Lev. R. s. 1היו אומות העולם … מתוך פַּנִּיקְטֵיהֶן(algum Ed.פַּנּוּקְ&#x27;) As nações estavam em perigo de ouvir a voz da revelação divina e de ficar assustadas fora de seus campos (Tan. T’rum. 9לתוך אהליהם), v. תָּרַזO Gen. R. s. 16 em três coisas que a Grécia estava antes de Roma,בנימוסין ובפניקטין וכ&#x27; Ar. (Ms. Parisבפנקיטין, Ed.בפנקיסין, בפנקיסוןNas leis, nos arranjos das vigílias do acampamento.</p>","gloss_language":"pt-BR"},{"sid":"Q01204","lemma":"פְּנִיקְיָא","gloss":"Phœnicia.","type":"pr. n.","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פְּנִקְ&#x27;</p><p><strong>Definição:</strong> Phœnicia.</p><p><strong>Notas e referências:</strong> Gen. R. s. 90 final, v.פְּלַסְטִינִי.</p>","gloss_language":"pt-BR"},{"sid":"Q01205","lemma":"פְּנַךְ","gloss":", Pa.פַּנֵּיךְPara dirigir, velocidade.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , Pa.פַּנֵּיךְPara dirigir, velocidade.</p><p><strong>Notas e referências:</strong> Targ. Jud. V, 22.מְפַנַּךְ, pl.מְפַנְּכִיןTarg. Não. Três, dois, Targ.</p>","gloss_language":"pt-BR"},{"sid":"Q01206","lemma":"פָּנָס","gloss":"(φανός) tocha; lanterna.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (φανός) tocha; lanterna.</p><p><strong>Notas e referências:</strong> Kel. II, 4פ&#x27; שיש בו וכUma lanterna que contém um recipiente para óleo, Tosef. VII, 11פ&#x27; של זכוכית וכUma lanterna de vidro.פוקטוTosef, Ber.פָאנָסEd Zuck. (Var.פנס); Ber. 53 b; Y. ib. VIII, 12 b bot. Ex. R.S. 15היה נוטל הפ&#x27; וכEle (o Senhor) pegou a tocha e levou luz diante deles (ref. ao Ex. XIII, 21). Ib. s. 25בשר ודם תלמוד טוען פ&#x27; וכEntre os seres humanos, o aluno carrega a luz diante de seu professor, não assim o Senhor...פְּנָסִיןGen. R. s. 3, implore.הדליק נרות ופLuzes e tochas. Ib. s. 68כבו את הנרות כבו הפApague as lâmpadas, apague as tochas. Koh. R. para XII, 7הדליק נרות ופ&#x27; לשמה וכEle acendeu lâmpadas e tochas em nome de Roma (como um augúrio para uma guerra contra Roma), e eles não queimariam, a. E.</p>","gloss_language":"pt-BR"},{"sid":"Q01207","lemma":"פנסטה","gloss":"Ver פְּשָׁטָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Y. B. Banho. VIII, 16 aבעי מימר פ&#x27;, leia:פְּשָׁטֵיה, v. פְּשָׁטָא</p>","gloss_language":"pt-BR"},{"sid":"Q01208","lemma":"פנע","gloss":"Y. Maasr. II, 49 dלפנעEd Krot.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> Y. Maasr. II, 49 dלפנעEd Krot.</p><p><strong>Notas e referências:</strong> , v. פָּנָה- Targ. Jer. XXIII, 29, v.נְפַע.</p>","gloss_language":"pt-BR"},{"sid":"Q01209","lemma":"פָּנַק","gloss":"Ser um homem livre, viver no luxo.חָטָא I).; tratar como um homem livre, ceder, estragar por indulgência.; para tratar ternamente, para cultivar, melhorar, embelezar.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> compararפּוּק)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Ser um homem livre, viver no luxo.חָטָא I).</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> tratar como um homem livre, ceder, estragar por indulgência.</p><p><strong>Notas e referências:</strong> Gen. R. s. 22 (ref. para Prov. XXIX, 21)שמְפַנֵּק וכ&#x27;, v. מָנוֹן; Yalk.ממתק).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para tratar ternamente, para cultivar, melhorar, embelezar.</p><p><strong>Notas e referências:</strong> Sifré Deut. 306מְפַנְּקִים; Yalk. ib. 942, v.עָדַן- Parte, passo.מְפוּנָּקdelicadamente criados. Mekh.עָדַןYalk. Ex. 339.היה מפ&#x27; ומת בידםEle era delicado e morreu sob suas mãos.</p>","gloss_language":"pt-BR"},{"sid":"Q01210","lemma":"פְּנַק","gloss":"Papai.פַּנֵּיקmesmo significado.; para deliciar a si mesmo.; Ser o nobre, ser imperioso.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> ch.,</p><p><strong>Definição:</strong> Papai.פַּנֵּיקmesmo significado.</p><p><strong>Notas e referências:</strong> Targ. Is. XXIII, 4.מְפַנַּק q. v.—V. אִסְפְּנִיקָא.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para deliciar a si mesmo.</p><p><strong>Notas e referências:</strong> Targ. Ps. XXXVII, 4; 11; a. fr.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Ser o nobre, ser imperioso.</p><p><strong>Notas e referências:</strong> Targ. Prov. XXIX, 21מִתְפְּנֵיק מן וכAquele que for cavalheiro em sua juventude, se tornará um servo e finalmente será expulso.מְפַנֵּק).</p>","gloss_language":"pt-BR"},{"sid":"Q01211","lemma":"פִּנְקַאי","gloss":"Ver פִּינְקֵאי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּינְקֵאי</p>","gloss_language":"pt-BR"},{"sid":"Q01212","lemma":"פַּנִּקְטִין","gloss":"Ver פַּנִּיקְטִין.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פנקיסין</p><p><strong>Notas e referências:</strong> , v. פַּנִּיקְטִין</p>","gloss_language":"pt-BR"},{"sid":"Q01213","lemma":"פִּנְקֵס","gloss":", V. Sub.פִּינ'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פִּנַקְסָא, פִּנַקְסָה</p><p><strong>Notas e referências:</strong> , V. Sub.פִּינ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"Q01214","lemma":"פַּנְקְרִיסִין","gloss":"(πάγχρυσοςNome de uma fruta, prob. damascos.","type":"Substantivo masculino plural","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְקְרִסִין</p><p><strong>Definição:</strong> (πάγχρυσοςNome de uma fruta, prob. damascos.</p><p><strong>Notas e referências:</strong> Y. Sot. I, 17 b topיפה מפ&#x27; וכ&#x27;... melhores foram as frutas tardias... do que os damascos &amp;c.; ib. IX, 24 b bot.; (Y. Peah VII, 20 a bot.מפרסקיןY. Sabb. III, 5 dוטעמן יפה כפE seu gosto era tão delicioso quanto o dos damascos, Y. Ter. II, 41 c bot.פ&#x27; … שלהןdamascos pressionados por gentios (prob. para ser lido, como Bab. ib. 38 b; Tosef. ib. IV (V), 11קַפְרִיסִין).</p>","gloss_language":"pt-BR"},{"sid":"Q01215","lemma":"פנרתא","gloss":"Ver פַּרְוָותָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Targ.פַּרְוָותָא</p>","gloss_language":"pt-BR"},{"sid":"Q01216","lemma":"פַּנְתָּא","gloss":"Ver אַפַּנְתָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. אַפַּנְתָּא</p>","gloss_language":"pt-BR"},{"sid":"Q01217","lemma":"פַּנְתֵּיר","gloss":"(πάνθηρ) pantera ou leopardo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְתֵּר</p><p><strong>Definição:</strong> (πάνθηρ) pantera ou leopardo.</p><p><strong>Notas e referências:</strong> - Pl.פַּנְתֵּירִין, פַּנְתֵּרִיןMidr. Até mais. para Ps. LXXVIII, 45 (expl.ערבib.)מין חיה הוא ושמה פ&#x27; והביאן וכ&#x27; (Nãoוהביאו) é uma espécie de besta selvagem chamada leopardos, e o Senhor enviou-lhes Yalk. ib. 820.</p>","gloss_language":"pt-BR"},{"sid":"Q01218","lemma":"פַּנְתֵּירִי","gloss":"Nome de uma jóia (corresp. para h.ישפה).","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Nome de uma jóia (corresp. para h.ישפה).</p><p><strong>Notas e referências:</strong> Targ. O. Ex. XXVIII, 20 ed. Berl.פַּנְטֵירֵי; Y. אַפַּנְטוּרִין, Ed. Vien.אפנטורע, corr. acc.); ib. XXXIX, 13 (ed. Vien.פַּנְתֵּרֵי, corr. acc.). Targ. XXVIII, 13פַּנְתֵּירִין.</p>","gloss_language":"pt-BR"},{"sid":"Q01219","lemma":"פַּנְתֵּר","gloss":"Ver preced..","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּנְתֵּרִי, פַּנְתֵּרִין</p><p><strong>Notas e referências:</strong> , V. Precedido. WDS.</p>","gloss_language":"pt-BR"},{"sid":"Q01220","lemma":"פָּס","gloss":"= אָפֵס, Pas, nome de dois Amoraim.","type":"Nome próprio masculino","detailsHtml":"<p><strong>Definição:</strong> = אָפֵס, Pas, nome de dois Amoraim.</p><p><strong>Notas e referências:</strong> Y. Taan. IV, 68 anos. Y. Yoma V, 43 anos. III, 64 por bot. (v. Pe. M’bo, p. 122 a).</p>","gloss_language":"pt-BR"},{"sid":"Q01221","lemma":"פַּס","gloss":"Ver פְּסַס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּסַס</p>","gloss_language":"pt-BR"},{"sid":"Q01222","lemma":"פַּס","gloss":"Tira, tira.; partição, placa, barreira.; pl. (V.פִּיסִּים) imposto;פַּסֵּי העירImposto municipal (usado para manter a segurança da cidade).","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> פָּסַס)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Tira, tira.</p><p><strong>Notas e referências:</strong> - Pl.פַּסִּים, פַּסִּין. Gen. R. s. 84 (ref. para Gen. XXXVII, 3 sq, a. Ps. LXVI, 5 sq; v.עֲלִּילָהPor que o odiaram? Isso (no curso dos eventos deve vir sobre isso)שיקרע הים לפניהם פ&#x27; פO mar será alugado antes deles em tiras (ed. Wil.פ̇ס̇י̇ם̇ פס יםPassagem faz alusão ao mar.פֶּרֶק) פס יד, palma, a mão do pulso até a ponta do dedo;פס רגלO pé no tornozelo, entrelaçar. comפִּסַּת, פִּיסַּת(constr. deפִּסָּהIb. (Expl.פסים, Gen. l. c.)שהיתה מגעת עד פס ידוo casaco chegou com suas mangas no pulso;שהיתה … בפס ידוera muito bom e leve, e poderia ser (comprimido e) escondido em sua mão (cmp.מַלְמֵלָהMeg.נתנה … על פס ידו וכ&#x27;se ele colocasse o T&#x27;fillin na testa ou na palma da mão. Yoma 87 aה̇ת̇ר̇פ̇ס[Leia:]אם ממון יש לו בידך ה̇ת̇ר לו פ̇ס̇ת יד וכSe lhe deves dinheiro, desamarra-lhe a mão, se não, se o ofendeste, arranja vários amigos em volta dele, para pedir perdão na presença deles. Prov. 938.מ̇ת̇ר̇פ̇ס בר̇צ̇י, Ps. LXIV, 31)מ̇ת̇יר̇ את הפ̇ס̇ ומ̇ת̇ר̇צ̇ה בכסףEle (Edom-Roma) abre sua mão (para suborno), e está apaziguado com prata; Ex. R. s. 35מתרת את הפס וכEla (Roma) abre o Yalk. Ps. 800שפושטין פסת יד … ואין עושין ר̇צ̇ון וכEles estendem a mão para aceitar a prata, e então não fazem o que os dadores desejam, Pes. 118 bשפושטין פסת יד וכM. (ed.שפושטין ידYoma 47 aעל פ&#x27; ידוAté o pulso, V.חָפָה; Sifra Vayikra, N&#x27;dab., ch. X, Par. 9חופה את פס ידו וכEle dobra a mão na frigideira. Ohol. I, 8שלשים בפס הרגל30 juntas no pé. Yalk. Sam. 143.חלילה … פ&#x27; יד ופ&#x27; רגל ועקב מגוליןNunca foram descobertos seus pulsos, seus pés ou seus calcanhares.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> partição, placa, barreira.</p><p><strong>Notas e referências:</strong> Erub. 5 aאם יש שם פם ארבעהSe uma barra de quatro pães for deixada ou colocada acima da fenda. Ib. 10b.עושה פם גבוה עשרה וכEle corta uma tábua com dez brotos de altura e quatro côvados de comprimento.עושין פ&#x27; לביראות וכVocê deve colocar divisórias em torno de estações de rega na forma de quatro peças de canto &amp;c., v.דְּיֹומַדIb. 11 aפַּסֵּי ביראותAs divisórias das estações de rega. I, 7, V.פַּץ.]</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> pl. (V.פִּיסִּים) imposto;פַּסֵּי העירImposto municipal (usado para manter a segurança da cidade).</p><p><strong>Notas e referências:</strong> Tosef. Peah IV, 9לפ&#x27; העיר לשנים וכEd.לענייA fim de ser avaliado para o imposto da cidade um deve ter sido um residente por doze meses; B. Bath. 8 a; Y. Peah VIII, 21 um bot.לפסין ולצדקותPara o imposto municipal e para as instituições de caridade, expl. para os salários de professores de escola pública; Y. B. Bath.לפסים ולזימיותpara impostos e multas da cidade.</p>","gloss_language":"pt-BR"},{"sid":"Q01223","lemma":"פַּס","gloss":",; Tira, tira.; פ' ידאPalm;פס רגלאPé, V.פִּיסְּתָא.; pedaço, porção, pão.; (de sua forma, cmp.כַּף) pá ou pá.; פ' דבירEstação de rega.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פַּסָּא, פִּסָּא, פִּי&#x27;</p><p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Tira, tira.</p><p><strong>Notas e referências:</strong> - Pl.פַּסֵּיTarg. O. Gen. XXXVII, 3; 23 (ed. Berl.פָּסֵי, פַּסֵיTarg. II Sam. XIII, 18 (ed. Wil.פַּסֵי).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> פ&#x27; ידאPalm;פס רגלאPé, V.פִּיסְּתָא.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> pedaço, porção, pão.</p><p><strong>Notas e referências:</strong> Bekh. 43 b, v.סְקִיפַסLam. R. a III, 16 Ar., v.פְּטִילִיקBer. VI, 10 b bot., v.פִּיסְּתָא.</p><p><strong>Número da acepção:</strong> —4)</p><p><strong>Definição:</strong> (de sua forma, cmp.כַּף) pá ou pá.</p><p><strong>Notas e referências:</strong> Lev. R. s. 24; s. 25 Ar., v.מַכּוֹשָׁאII...</p><p><strong>Número da acepção:</strong> *5)</p><p><strong>Definição:</strong> פ&#x27; דבירEstação de rega.</p><p><strong>Notas e referências:</strong> Targ. Y. I Deu. XXXIII, 3ושריין כמין פ&#x27; דב&#x27; (NãoדבַרEles descansam em uma estação de rega.על פום דבירוי).</p>","gloss_language":"pt-BR"},{"sid":"Q01224","lemma":"פְּסָא","gloss":"Ver פְּסֵי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּסֵי</p>","gloss_language":"pt-BR"},{"sid":"Q01225","lemma":"פסאני","gloss":"Ver פִּסְיֹונִי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּסְיֹונִי</p>","gloss_language":"pt-BR"},{"sid":"Q01226","lemma":"פְּסָאקָא","gloss":"P’sa'a, sobrenome de um R. Yitsya.","type":"pr. n.","detailsHtml":"<p><strong>Definição:</strong> P’sa&#x27;a, sobrenome de um R. Yitsya.</p><p><strong>Notas e referências:</strong> Lam. R. para I, 9ר&#x27; יצחק פ&#x27; (Yalk. É. 302יצחק פסיקתא); cmp.פַּסְקַת.</p>","gloss_language":"pt-BR"},{"sid":"Q01227","lemma":"פָּסַג","gloss":", Pi.פִּסֵּג; Para dividir, se ramificar, denom.פְּסִיגָה.; (denom. deפְּסִיגָה) para cortar sprays, para diminuir.; Para cortar o caminho através de galhos, passar por florestas, vinhedos &c., invasão; para levar através de moitas &c. B. Kam. 81 bהתועה … מַפְסִיג ויורד מפסיג ועולה וכSe alguém perder seu caminho em vinhedos, ele pode cortar seu caminho através de cima e para baixo.הרואה … מפסיג וכ\" aquele que vê um companheiro perdido em vinhedos, pode dar um caminho para ele... até que ele traga-lhe C; Tosef. B. Mets. II, 28מְפַסְּגוֹ בשדות וכ' pode levá-lo através de campos e vinhedos.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , Pi.פִּסֵּג</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para dividir, se ramificar, denom.פְּסִיגָה.</p><p><strong>Notas e referências:</strong> Par. XI, 9מְפַסְּגֹו ואוגדוEle corta os talos de hissopo e os amarra;פְּסָגֹו ולא אגדוSe ele cortou, mas falhou em amarrá-los.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> (denom. deפְּסִיגָה) para cortar sprays, para diminuir.</p><p><strong>Notas e referências:</strong> B. Kam. 119 bמְפַסְּגֵי אילנות ומפסגי גפנים(Ms. F.ומפסיקיAr.ומפסקי(Tosef. ib. XI, 18)מפסקי גפניםApenas). M. Kat. 3 aאין מְפַסְּגִין באילןVocê não deve árvores finas (durante a semana festiva; Rashi: apoiar os galhos); e.. - Tosef. B. Mets. II, 28, V. Infra.</p><p><strong>Definição:</strong> Para cortar o caminho através de galhos, passar por florestas, vinhedos &amp;c., invasão; para levar através de moitas &amp;c. B. Kam. 81 bהתועה … מַפְסִיג ויורד מפסיג ועולה וכSe alguém perder seu caminho em vinhedos, ele pode cortar seu caminho através de cima e para baixo.הרואה … מפסיג וכ&quot; aquele que vê um companheiro perdido em vinhedos, pode dar um caminho para ele... até que ele traga-lhe C; Tosef. B. Mets. II, 28מְפַסְּגוֹ בשדות וכ&#x27; pode levá-lo através de campos e vinhedos.</p><p><strong>Notas e referências:</strong> na mesma fonteהוא עצמו … מפסיג וכEd.מפסגEle que se perdeu pode fazer o seu caminho.</p>","gloss_language":"pt-BR"},{"sid":"Q01228","lemma":"פְּסַג","gloss":",; Dividir, cortar.; Para quebrar uma armadilha, escapar.; Dividir.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Dividir, cortar.</p><p><strong>Notas e referências:</strong> Targ. Y. Gen. XV, 10 (O.פלג, h. textoבתרIb. XXVI, 31.פָּסִיג. Gen. R. s.פ&#x27; תִּרְעָךְQue a tua má sorte seja quebrada (não te aconteça mais mal, que permita o significado de teu portão (תַּרְעָא) ser quebrado &#x27;, é corrigido paraיסוג תורעך, v. סוּגCh.).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para quebrar uma armadilha, escapar.</p><p><strong>Notas e referências:</strong> Gen. R. s. 79כד שמע … פַּסְגָּאQuando R.S. ouviu a voz celestial dizer demos (v.דִּימוֹסII), ele (o pássaro) escapou; Yalk. ib. 133.פשגא(Ar.הות פשגה- B. Kam. 81 b.דנִיפְסוֹגque ele pode ser autorizado a romper (o vinhedo), V. Preced.</p><p><strong>Definição:</strong> Dividir.</p><p><strong>Notas e referências:</strong> Targ. Y. Lev. I, 12יַפְסֵיג(algum Ed.יְפַסֵּיג; ed. Vien.פַּיְסֵג, corr. acc.). Targ. Y. I. Ex. XXIX, 17תַּפְסֵיג(Y. IIתְּפַסֵּג; ed. Vien.תְּפַסֵּקLam. R. a V, 5מְפַסֵּג ליה וכ&#x27; (ed. Wil.מפסלEle o cortou membro a membro.</p>","gloss_language":"pt-BR"},{"sid":"Q01229","lemma":"פַּסְגָּא","gloss":"Peça, parte. Targ. Y. Gen. XXVI, 31.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: פִּסְ&#x27;, פִּיסְ&#x27;</p><p><strong>Definição:</strong> Peça, parte. Targ. Y. Gen. XXVI, 31.</p><p><strong>Notas e referências:</strong> Ib. XV, 10. — Pl.פַּסְגִּין, פִּסְ&#x27;, פִּסְגַּיָּא, פִּיIb. Targ. Y. Ex. XXIX, 17 anos.פִּסְגָּתָא, פִּיY. Ned.תמחוי החוזר) פCortem porções na placa.</p>","gloss_language":"pt-BR"},{"sid":"Q01230","lemma":"פִּסְגָּה","gloss":"(precedida. wds., v.פְּסִיגָה); Branch, galho, opp.אשכולO tronco com os cachos de uva.; (b. h.) pr. n. Pisgah, o cume do Monte Nebo.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (precedida. wds., v.פְּסִיגָה)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Branch, galho, opp.אשכולO tronco com os cachos de uva.</p><p><strong>Notas e referências:</strong> O tronco com os cachos de uva.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> (b. h.) pr. n. Pisgah, o cume do Monte Nebo.</p><p><strong>Notas e referências:</strong> Sifré Deut. 357 (ref. a XXXIV, 1)מה פ&#x27; זו מופרשת מן האשכול ואינה מופרשת וכ&#x27;como o galho é separado do tronco, mas não desapegado, assim foi o túmulo de Moisés &amp; c., v.תָאַם; Yalk. ib. 963.</p>","gloss_language":"pt-BR"},{"sid":"Q01231","lemma":"פָּסַד","gloss":"Cortar, diminuir;פָּסֵד(cmp.פגם, פסל) perder em valor, deteriorar.; Sofrer perda, perder, estar em desvantagem.; para ferir, causar perda.; Perder.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> Cortar, diminuir;פָּסֵד(cmp.פגם, פסל) perder em valor, deteriorar.</p><p><strong>Notas e referências:</strong> Y. Maasr. V, implore. 51 cשהן פְּסֵידִיןPorque eles estragam;חטין אינן פO trigo não estraga.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Sofrer perda, perder, estar em desvantagem.</p><p><strong>Notas e referências:</strong> B. Mets. III, 4, sq.אם כן מה ה&#x27; הרמאיSe esta é a lei, o que o homem desonesto perde (que risco corre para impedi-lo de reivindicar mais do que seu devido)? Ber.הקורא … לא הAquele que lê o Sh&#x27;m&#x27;a depois disso, não perde nada.לא ה&#x27; ברכותEle não perde as bênçãos (ele pode recitar as bênçãos anteriores e seguindo o Sh&#x27;m&#x27;a como de costume). Y. ib. I, 2 b topאין תפלה מַפְסֶדֶתuma oração nunca perde seu valor. Gen. R. s. 70נדרו והִפְסִידוּJurou e sofreu assim. Keth. XIII, 3אדמון אומר … הִפְסַרְתִּיsobre o qual Admon disse, devo estar em desvantagem, porque sou um herdeiro masculino?</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para ferir, causar perda.</p><p><strong>Notas e referências:</strong> Tosef. Apostas. II, 6שמא יַפְסִידוּ את וכPara que não façam mal aos habitantes.והפסיד אלא, leia:והפשיר עמו, v. פָּשַׁר.]</p><p><strong>Definição:</strong> Perder.</p><p><strong>Notas e referências:</strong> Pes. 50 b.יש זריז ונ&#x27;, v. זָרִיז; Tosef. Yeb. IV, 8ומַפְסִיד( Hif.).</p>","gloss_language":"pt-BR"},{"sid":"Q01232","lemma":"פְּסַד","gloss":",; para ser diminuído, escasso.; para diminuir, destruir.; para arruinar, estragar.; Ferir, estragar, arruinar.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para ser diminuído, escasso.</p><p><strong>Notas e referências:</strong> Targ. Y. Gen. XLVII, 16 (h. texto)אפס).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para diminuir, destruir.</p><p><strong>Notas e referências:</strong> Targ. Ps. XLIV, 3 (ed. Lag.שלח).</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para arruinar, estragar.</p><p><strong>Notas e referências:</strong> Pes. 55 b.פַּסְדָא לה ביעי לגמריEla (a galinha da eclosão) estragou os ovos completamente (os tornou impróprios para serem comidos).פָּסֵידIb.אכתי לא פְסֵידֵי ביעי וכ&#x27; (Ms. M.פסיד לה ביעא;Srta. K.לא פַסְדָּה להOs ovos ainda não estão completamente estragados.</p><p><strong>Definição:</strong> Ferir, estragar, arruinar.</p><p><strong>Notas e referências:</strong> Keth. 56 aאיהו הוא דא&#x27; אנפשיהEle trouxe a perda sobre si mesmo. B. Bath. 139 bאינהו אַפְסִידוּ אנפשייהוEles trouxeram a perda. Sabb. 108bאַפְסוּדֵי קא מַפְסִידְנָא ליהEu vitifico. Keth. 61 b.אַפְסְדַת לסעודתא וכ&#x27; (Rashi:אַפְסַדְתָּאVocê estragou a refeição do rei. B. Mets. 117 B.כמה מַפְסְדָה עלייה בביתAr. (ed.מפסידPor quanto a história superior prejudica a durabilidade da história inferior?</p>","gloss_language":"pt-BR"},{"sid":"Q01233","lemma":"פְּסֵדָא","gloss":"Ver פְּסִידָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פְּסִידָא</p>","gloss_language":"pt-BR"},{"sid":"Q01234","lemma":"פסדיות","gloss":"Ver סַדְיָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Y’lamd. para Gen. XXVIII, 10 sq, quot. em Ar., leia:בֵּי סַדְיוֹת, v. סַדְיָא</p>","gloss_language":"pt-BR"},{"sid":"Q01235","lemma":"פִּסָּה","gloss":"Ver פַּס II.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , Constr.פִּסַּת, v. פַּסII</p>","gloss_language":"pt-BR"},{"sid":"Q01236","lemma":"פָּסָה","gloss":"Ver פסי.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פסי</p>","gloss_language":"pt-BR"},{"sid":"Q01237","lemma":"פְּסוּגָא","gloss":"(פְּסַג) pedaço.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (פְּסַג) pedaço.</p><p><strong>Notas e referências:</strong> - Pl.פְּסוּגַיָּאTarg. Y. Ex. XII, 40, Targ. I Chr. VII, 21ביני פ&#x27; no pacto entre as peças, v.בְּתָרִים; Targ. Y. I. Lev. XXVI, 42פִּיסּוּגַיָּא.</p>","gloss_language":"pt-BR"},{"sid":"Q01238","lemma":"פסוורוס","gloss":"Ver פִּוְוסָרוֹס.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. פִּוְוסָרוֹס</p>","gloss_language":"pt-BR"},{"sid":"Q01239","lemma":"פְּסוֹל","gloss":"(denom. deפָּסוּלser ou tornar-se desqualificado, incapaz.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> (denom. deפָּסוּלser ou tornar-se desqualificado, incapaz.</p><p><strong>Notas e referências:</strong> Homens. 100 aליפסל ליקדוש ולִיפְסוֹל(Sairליפסל, v. Rabb. D. S. a. l. nota) deixe-o tornar-se sagrado (por ser colocado em um vaso sagrado) e, posteriormente, tornar-se impróprio (quando se torna atrasado); ib. b; Yoma 29 bתקדוש ותִפְסוֹל; a. e.—V. פְּסַל.</p>","gloss_language":"pt-BR"}],120);
